def export_typescript_types(out_path: Path | str = "frontend/src/types/generated.ts") -> None:
    path = Path(out_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(TYPESCRIPT_HEADER.strip() + "\n", encoding="utf-8")
    print(f"TypeScript contracts written to {path}")


if __name__ == "__main__":
    export_typescript_types()
